        <div class="hotkey-hint">Press <kbd>Space</kbd> or <kbd>Enter</kbd> to restart | <kbd>Esc</kbd> for menu</div>
      </div>
    </div>

    <!-- Control Guide -->
    <div class="controls-guide">
      <div class="control-box">
        <div class="control-box-title" style="color: var(--p1-color)">
          <div class="color-dot dot-p1"></div>
          <span id="guideP1Name">Snake 1 (Green)</span>
        </div>
        <div>Controls: <strong>Arrow Keys</strong> (&uarr; &darr; &larr; &rarr;)</div>
